-- Prisma on D1 stores DateTime as text. Seed rows used integer milliseconds.
-- A single ISO value in an otherwise numeric column makes findMany fail.
UPDATE "Session" SET "expires" = strftime('%Y-%m-%dT%H:%M:%fZ', "expires" / 1000.0, 'unixepoch') WHERE typeof("expires") IN ('integer', 'real');
